-- Paket ABT "abt-alamat-putusan-28okt" (28 Okt 2026): keterangan arah di dalam KURUNG pada alamat pihak dibuang di PUTUSAN (relaas tetap utuh). 6 variabel diubah (7047, 7048, 8700, 8890, 9349, 9350), 2 fungsi paket 27 Okt diganti, 3 fungsi baru (AP).
-- Prasyarat: paket pihak-urut-ecourt-27okt dan pihak-urut-sisa-28okt sudah terpasang.
-- PULIH (deterministik): variabel dikembalikan dari tabel sementara pu_lama (dibuat pulih-satker.sh dari cadangan/abt_variabel-sebelum.sql) HANYA bila isinya masih isi BARU paket dan baris cadangan masih isi LAMA yang diharapkan.
-- Dua fungsi paket 27 Okt dikembalikan oleh pulih-satker.sh (-FUNGSI-LAMA.sql) SESUDAH ini, lalu fungsi AP dihapus bila tak ada yang memanggilnya.
START TRANSACTION;
UPDATE abt_variabel a JOIN pu_lama l ON l.no_var=a.no_var SET a.nama=l.nama, a.data_type=l.data_type, a.data_tabel=l.data_tabel, a.data_kolom=l.data_kolom, a.urutan_data=l.urutan_data, a.referensi=l.referensi, a.sql_query=l.sql_query, a.default_data=l.default_data, a.multi_sidang=l.multi_sidang, a.locked=l.locked, a.modifier=l.modifier, a.modified=l.modified WHERE (a.no_var=7047 AND MD5(a.nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND a.data_type='data_sql' AND MD5(a.sql_query)='c8fdb0dade2c0d8c7549caeabca6c08b') AND (l.no_var=7047 AND MD5(l.nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND l.data_type='data_sql' AND MD5(l.sql_query)='f548b43be1206974a88aa1cd84b66822');
