SELECT IF((SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=7047 AND MD5(nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND data_type='data_sql' AND MD5(sql_query)='f548b43be1206974a88aa1cd84b66822') OR (no_var=7048 AND MD5(nama)='0d46332b5be50992e27dfcebf6ec1de4' AND data_type='data_sql' AND MD5(sql_query)='485001ad3b68a7ab053d8e875ca001c4') OR (no_var=8700 AND MD5(nama)='cc04924b6d60cd2fe9d0082b9fba493a' AND data_type='data_sql' AND MD5(sql_query)='28e503d1c8a2d7ca42f4650857adb3aa') OR (no_var=8890 AND MD5(nama)='af7b94e4c0ef1b79bee1c4bba11bbe8a' AND data_type='data_sql' AND MD5(sql_query)='cc33da9647af6855dcf50700f4476a3c') OR (no_var=9349 AND MD5(nama)='a15f9d0715b5eae1e50b009c8b557575' AND data_type='data_sql' AND MD5(sql_query)='18ff1d4ac1a30da6295f73aa87dac917') OR (no_var=9350 AND MD5(nama)='40caa4ef1d8b274b9a851f0c6db9ece6' AND data_type='data_sql' AND MD5(sql_query)='e6a0c12edde5c6eb6a64511b2fba7047'))) = 6, 'VARIABEL KEMBALI', CONCAT('PULIH TIDAK LENGKAP - baris diubah yang sudah kembali ', (SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=7047 AND MD5(nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND data_type='data_sql' AND MD5(sql_query)='f548b43be1206974a88aa1cd84b66822') OR (no_var=7048 AND MD5(nama)='0d46332b5be50992e27dfcebf6ec1de4' AND data_type='data_sql' AND MD5(sql_query)='485001ad3b68a7ab053d8e875ca001c4') OR (no_var=8700 AND MD5(nama)='cc04924b6d60cd2fe9d0082b9fba493a' AND data_type='data_sql' AND MD5(sql_query)='28e503d1c8a2d7ca42f4650857adb3aa') OR (no_var=8890 AND MD5(nama)='af7b94e4c0ef1b79bee1c4bba11bbe8a' AND data_type='data_sql' AND MD5(sql_query)='cc33da9647af6855dcf50700f4476a3c') OR (no_var=9349 AND MD5(nama)='a15f9d0715b5eae1e50b009c8b557575' AND data_type='data_sql' AND MD5(sql_query)='18ff1d4ac1a30da6295f73aa87dac917') OR (no_var=9350 AND MD5(nama)='40caa4ef1d8b274b9a851f0c6db9ece6' AND data_type='data_sql' AND MD5(sql_query)='e6a0c12edde5c6eb6a64511b2fba7047'))), ' dari 6 (diubah orang sesudah dipasang? dibiarkan)')) AS hasil;
